/**
 * Editorial display order for a language's SENTENCE examples.
 *
 * Why this is not simply an edit to examples.json: that file is generated by
 * scripts/extract_examples.py, so a hand-reordering would be lost the next time it runs.
 * Worse, scripts/extract_verdicts.py binds each annotator verdict to an example by its
 * NUMERIC POSITION in that file (`key = int(float(a))` off the sheet's column A), so
 * physically reordering the items would silently move the verdicts onto the wrong ones --
 * here it would have attached the "Minor fix / Mistranslation" verdict to an example the
 * annotators marked Approved.
 *
 * So the order is expressed here instead, as a permutation of the generated order, and
 * the browser carries the verdict indices through it rather than around it.
 *
 * Hindi: [2, 1, 0] swaps the first and third sentences. The constellation's detail panel
 * shows a language's FIRST sentence, so this is what puts the Convention on Biological
 * Diversity example on the language map. It is also the better example to lead with by the
 * annotators' own marks -- Approved with issue type None, against Minor fix /
 * Mistranslation for the Reserve Bank sentence it displaces.
 */
export const SENTENCE_ORDER = {
  Hindi: [2, 1, 0],
};

/**
 * The permutation for a language as an array of original indices, or the identity when
 * there is no override. Length-checked, so an override left behind after the generator
 * changes the number of examples falls back to the generated order instead of dropping or
 * duplicating one.
 */
export const sentencePerm = (lang, list) => {
  const p = SENTENCE_ORDER[lang];
  const n = list?.length ?? 0;
  if (p && p.length === n && new Set(p).size === n && p.every((i) => i >= 0 && i < n)) return p;
  return Array.from({ length: n }, (_, i) => i);
};

/** A language's sentence examples in display order. */
export const orderSentences = (lang, list) =>
  sentencePerm(lang, list).map((i) => list[i]);

/**
 * Which sentence a language's list OPENS on, as a 1-based index into the generated order,
 * overriding the verdict-derived pointer.
 *
 * The verdict pointer means "the first example in the ANNOTATORS' order that is usable",
 * and it follows its example through the permutation above -- so after the Hindi swap it
 * still pointed at the Reserve Bank sentence, now sitting third. That left the map and the
 * list leading with different examples, and the list leading with the weaker of the two.
 *
 * Hindi: 3 is the Convention on Biological Diversity sentence, which the workbook marks
 * Approved with issue type None. The one it displaces is Minor fix / Mistranslation. An
 * override here can only ever promote an example an annotator marked usable -- that is a
 * fact about this entry, checked against the sheet, not something the code can enforce, so
 * any addition to this map needs the same check.
 */
export const SENTENCE_FIRST = {
  Hindi: 3,
};

